import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { BookCard } from './BookCover';
import { STATUSES, getStatus } from '../data/library';
import { ACCENT_COLORS } from '../data/library';

const STATUS_GROUPS = [
  { id: 'reading',      label: 'Currently Reading' },
  { id: 'want-next',    label: 'Next Book!' },
  { id: 'want-someday', label: 'Maybe Someday' },
  { id: 'want-meh',     label: 'Yeah Whatever' },
  { id: 'finished',     label: 'Finished' },
  { id: 'dnf',          label: 'Did Not Finish' },
];

function StarDisplay({ rating }) {
  if (!rating) return null;
  return <span style={{ color: '#b07d28', fontSize: 11 }}>{'★'.repeat(rating)}{'☆'.repeat(5 - rating)}</span>;
}

function ProgressBar({ book }) {
  if (!book.pages || book.status !== 'reading') return null;
  const pct = Math.min(100, Math.round((book.progress / book.pages) * 100));
  return (
    <div style={{ marginTop: 3 }}>
      <div style={{ height: 3, background: 'var(--paper-3)', borderRadius: 2, overflow: 'hidden' }}>
        <div style={{ height: '100%', width: `${pct}%`, background: '#2e7d5e', borderRadius: 2 }} />
      </div>
      <div style={{ fontSize: 9, color: 'var(--ink-4)', marginTop: 2, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>p.{book.progress}/{book.pages} · {pct}%</div>
    </div>
  );
}

// ── Group manager panel ────────────────────────────────────────
function GroupManager({ groups, books, onUpdate, onClose }) {
  const [items, setItems] = useState(groups.map(g => ({ ...g })));
  const [newName, setNewName] = useState('');
  const [newColor, setNewColor] = useState(ACCENT_COLORS[0]);

  const add = () => {
    if (!newName.trim()) return;
    setItems(prev => [...prev, { id: uuidv4(), name: newName.trim(), color: newColor }]);
    setNewName('');
  };

  return (
    <div onClick={e => e.target === e.currentTarget && onClose()}
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 200, padding: 20 }}>
      <div style={{ background: 'var(--paper-card)', borderRadius: 12, width: 420, maxHeight: '80vh', display: 'flex', flexDirection: 'column', overflow: 'hidden', boxShadow: 'var(--shadow-md)' }}>
        <div style={{ padding: '14px 18px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
          <span style={{ fontSize: 14, fontWeight: 500, color: 'var(--ink)' }}>Manage groups</span>
          <button onClick={onClose} style={{ fontSize: 12, color: 'var(--ink-3)', cursor: 'pointer' }}>✕</button>
        </div>
        <div style={{ flex: 1, overflowY: 'auto', padding: '12px 18px' }}>
          {items.map(g => {
            const count = books.filter(b => b.groupId === g.id).length;
            return (
              <div key={g.id} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8, padding: '6px 0', borderBottom: '1px solid var(--paper-3)' }}>
                <div style={{ position: 'relative', flexShrink: 0 }}>
                  <div style={{ width: 18, height: 18, borderRadius: '50%', background: g.color, cursor: 'pointer' }} />
                  <input type="color" value={g.color} onChange={e => setItems(prev => prev.map(i => i.id === g.id ? { ...i, color: e.target.value } : i))}
                    style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer', width: '100%', height: '100%' }} />
                </div>
                <input value={g.name} onChange={e => setItems(prev => prev.map(i => i.id === g.id ? { ...i, name: e.target.value } : i))}
                  style={{ flex: 1, padding: '4px 8px', fontSize: 13, borderRadius: 5 }} />
                <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', minWidth: 40 }}>{count} book{count !== 1 ? 's' : ''}</span>
                <button onClick={() => { if (window.confirm('Remove group? Books become ungrouped.')) setItems(prev => prev.filter(i => i.id !== g.id)); }}
                  style={{ fontSize: 11, color: 'var(--ink-4)', cursor: 'pointer', background: 'none', border: 'none' }}
                  onMouseEnter={e => e.currentTarget.style.color = 'var(--red)'}
                  onMouseLeave={e => e.currentTarget.style.color = 'var(--ink-4)'}>✕</button>
              </div>
            );
          })}
        </div>
        <div style={{ padding: '10px 18px', borderTop: '1px solid var(--paper-3)', flexShrink: 0 }}>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 10 }}>
            <div style={{ position: 'relative', flexShrink: 0 }}>
              <div style={{ width: 26, height: 26, borderRadius: '50%', background: newColor, cursor: 'pointer', border: '2px solid var(--paper-3)' }} />
              <input type="color" value={newColor} onChange={e => setNewColor(e.target.value)} style={{ position: 'absolute', inset: 0, opacity: 0, cursor: 'pointer', width: '100%', height: '100%' }} />
            </div>
            <input value={newName} onChange={e => setNewName(e.target.value)} onKeyDown={e => e.key === 'Enter' && add()}
              placeholder="New group name…" style={{ flex: 1, padding: '7px 10px', fontSize: 13, borderRadius: 6 }} />
            <button onClick={add} style={{ fontSize: 12, padding: '7px 14px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Add</button>
          </div>
          <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
            <button onClick={onClose} style={{ fontSize: 12, padding: '6px 14px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--ink-3)', cursor: 'pointer' }}>Cancel</button>
            <button onClick={() => { onUpdate(items); onClose(); }} style={{ fontSize: 12, padding: '6px 18px', borderRadius: 6, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>Save</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Main LibraryView ───────────────────────────────────────────
export default function LibraryView({ books, groups = [], onEdit, onAdd, onUpdateGroups, onOpenArchive }) {
  const [displayMode, setDisplayMode] = useState('list'); // 'list' | 'covers'
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterGroup, setFilterGroup]   = useState('all');
  const [search, setSearch] = useState('');
  const [showGroupManager, setShowGroupManager] = useState(false);
  const [collapsedGroups, setCollapsedGroups] = useState({}); // { [statusId]: true }
  const toggleGroup = (id) => setCollapsedGroups(c => ({ ...c, [id]: !c[id] }));

  const filtered = books
    .filter(b => filterStatus === 'all' || b.status === filterStatus)
    .filter(b => filterGroup === 'all' || b.groupId === filterGroup)
    .filter(b => !search || b.title.toLowerCase().includes(search.toLowerCase()) || b.author?.toLowerCase().includes(search.toLowerCase()));

  const stats = {
    reading:  books.filter(b => b.status === 'reading').length,
    finished: books.filter(b => b.status === 'finished').length,
    want:     books.filter(b => b.status?.startsWith('want')).length,
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Topbar */}
      <div style={{ padding: '12px 20px 10px', borderBottom: '1px solid var(--paper-3)', flexShrink: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <div>
            <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--ink)' }}>Library</div>
            <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
              {books.length} books · {stats.reading} reading · {stats.finished} finished · {stats.want} to read
            </div>
          </div>
          <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, alignItems: 'center' }}>
            {/* View toggle */}
            <div style={{ display: 'flex', border: '1px solid var(--paper-3)', borderRadius: 7, overflow: 'hidden' }}>
              {[['list','≡','List'],['covers','⊞','Covers']].map(([mode, icon, label]) => (
                <button key={mode} onClick={() => setDisplayMode(mode)}
                  style={{ padding: '5px 12px', fontSize: 11, border: 'none', background: displayMode === mode ? 'var(--accent-light)' : 'transparent', color: displayMode === mode ? 'var(--accent)' : 'var(--ink-3)', cursor: 'pointer', borderRight: mode === 'list' ? '1px solid var(--paper-3)' : 'none', display: 'flex', alignItems: 'center', gap: 4 }}>
                  {icon} {label}
                </button>
              ))}
            </div>
            <button onClick={() => setShowGroupManager(true)}
              style={{ fontSize: 11, padding: '6px 12px', borderRadius: 7, border: '1px solid var(--paper-3)', color: 'var(--ink-2)', background: 'var(--paper-card)', cursor: 'pointer' }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent-2)'; e.currentTarget.style.color = 'var(--accent)'; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--paper-3)'; e.currentTarget.style.color = 'var(--ink-2)'; }}>
              ⊙ Groups
            </button>
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
              style={{ width: 150, padding: '6px 12px', fontSize: 12 }} />
            <button onClick={onAdd} style={{ fontSize: 12, padding: '6px 16px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer', whiteSpace: 'nowrap' }}>
              + Add book
            </button>
          </div>
        </div>

        {/* Filters */}
        <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap', alignItems: 'center' }}>
          {/* Status pills */}
          <StatusPill id="all" label="All" count={books.length} active={filterStatus === 'all'} color="var(--ink-3)" bg="var(--paper-3)" onClick={() => setFilterStatus('all')} />
          {STATUSES.map(s => {
            const cnt = books.filter(b => b.status === s.id).length;
            if (cnt === 0) return null;
            return <StatusPill key={s.id} id={s.id} label={s.label} count={cnt} active={filterStatus === s.id} color={s.color} bg={s.bg} onClick={() => setFilterStatus(filterStatus === s.id ? 'all' : s.id)} />;
          })}
          {groups.length > 0 && <div style={{ width: 1, height: 14, background: 'var(--paper-3)' }} />}
          {groups.length > 0 && (
            <select value={filterGroup} onChange={e => setFilterGroup(e.target.value)}
              style={{ fontSize: 11, padding: '3px 22px 3px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)' }}>
              <option value="all">All groups</option>
              {groups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
            </select>
          )}
        </div>
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '16px 20px' }}>
        {displayMode === 'list' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
            {STATUS_GROUPS.map(sg => {
              const sgBooks = filtered.filter(b => b.status === sg.id);
              if (sgBooks.length === 0) return null;
              const st = getStatus(sg.id);
              return (
                <div key={sg.id}>
                  <button onClick={() => toggleGroup(sg.id)} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: collapsedGroups[sg.id] ? 0 : 8, width: '100%', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 0', textAlign: 'left' }}>
                    <span style={{ fontSize: 9, color: 'var(--ink-4)', transition: 'transform 0.15s', transform: collapsedGroups[sg.id] ? 'rotate(0deg)' : 'rotate(90deg)', display: 'inline-block' }}>▶</span>
                    <div style={{ width: 7, height: 7, borderRadius: '50%', background: st.color }} />
                    <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--ink-2)', letterSpacing: '0.06em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{sg.label}</span>
                    <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{sgBooks.length}</span>
                  </button>
                  {!collapsedGroups[sg.id] && <div style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 10, overflow: 'hidden' }}>
                    {sgBooks.map((b, i) => {
                      const group = groups.find(g => g.id === b.groupId);
                      return (
                        <div key={b.id}
                          style={{ display: 'grid', gridTemplateColumns: '10px 1fr auto', alignItems: 'center', gap: 12, padding: '10px 16px', borderBottom: i < sgBooks.length - 1 ? '1px solid var(--paper-3)' : 'none', transition: 'background 0.12s' }}
                          onMouseEnter={e => e.currentTarget.style.background = 'var(--paper-2)'}
                          onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                          <div style={{ width: 10, height: 10, borderRadius: '50%', background: b.color, flexShrink: 0, cursor: 'pointer' }} onClick={() => onEdit(b)} />
                          <div style={{ cursor: 'pointer' }} onClick={() => onEdit(b)}>
                            <div style={{ fontSize: 13, fontWeight: 500, color: 'var(--ink)' }}>{b.title}</div>
                            <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>
                              {b.author}{b.year ? ` · ${b.year < 0 ? Math.abs(b.year) + ' BCE' : b.year}` : ''}
                              {group ? <span style={{ color: group.color, marginLeft: 6 }}>· {group.name}</span> : ''}
                            </div>
                            <ProgressBar book={b} />
                            {b.review && <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 3 }}>"{b.review}"</div>}
                          </div>
                          <div style={{ textAlign: 'right', flexShrink: 0, display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 4 }}>
                            <StarDisplay rating={b.rating} />
                            {b.genre && <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{b.genre}</div>}
                            {onOpenArchive && (
                              <button onClick={e => { e.stopPropagation(); onOpenArchive(b.id); }}
                                style={{ fontSize: 10, padding: '2px 8px', borderRadius: 5, border: '1px solid var(--paper-3)', color: 'var(--ink-3)', background: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginTop: 2 }}
                                onMouseEnter={e => { e.currentTarget.style.color = 'var(--accent)'; e.currentTarget.style.borderColor = 'var(--accent-2)'; }}
                                onMouseLeave={e => { e.currentTarget.style.color = 'var(--ink-3)'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
                                notes →
                              </button>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>}
                </div>
              );
            })}
          </div>
        )}

        {displayMode === 'covers' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
            {STATUS_GROUPS.map(sg => {
              const sgBooks = filtered.filter(b => b.status === sg.id);
              if (sgBooks.length === 0) return null;
              const st = getStatus(sg.id);
              return (
                <div key={sg.id}>
                  <button onClick={() => toggleGroup(sg.id)}
                    style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: collapsedGroups[sg.id] ? 0 : 12, width: '100%', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 0', textAlign: 'left' }}>
                    <span style={{ fontSize: 9, color: 'var(--ink-4)', display: 'inline-block', transition: 'transform 0.15s', transform: collapsedGroups[sg.id] ? 'rotate(0deg)' : 'rotate(90deg)' }}>▶</span>
                    <div style={{ width: 7, height: 7, borderRadius: '50%', background: st.color }} />
                    <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--ink-2)', letterSpacing: '0.06em', textTransform: 'uppercase', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{sg.label}</span>
                    <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)' }}>{sgBooks.length}</span>
                  </button>
                  {!collapsedGroups[sg.id] && (
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
                      {sgBooks.map(b => (
                        <div key={b.id} style={{ display: 'flex', flexDirection: 'column', gap: 6, width: 120 }}>
                          <BookCard book={b} status={st} onClick={() => onEdit(b)} />
                          <div style={{ fontSize: 11, color: 'var(--ink-2)', lineHeight: 1.35, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{b.title}</div>
                          <div style={{ fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{b.author}</div>
                          <StarDisplay rating={b.rating} />
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {filtered.length === 0 && (
          <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic' }}>
            {search ? 'No books match your search.' : 'Your library is empty — add your first book.'}
          </div>
        )}
      </div>

      {showGroupManager && <GroupManager groups={groups} books={books} onUpdate={onUpdateGroups} onClose={() => setShowGroupManager(false)} />}
    </div>
  );
}

function StatusPill({ label, count, active, color, bg, onClick }) {
  return (
    <button onClick={onClick}
      style={{ fontSize: 10, padding: '3px 10px', borderRadius: 20, border: `1px solid ${active ? color : 'var(--paper-3)'}`, background: active ? bg + '44' : 'transparent', color: active ? color : 'var(--ink-3)', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', display: 'flex', alignItems: 'center', gap: 4 }}>
      {label} <span style={{ opacity: 0.7 }}>{count}</span>
    </button>
  );
}
